WITH ranked_items AS (SELECT d.d_year, d.d_quarter_seq, cr.cr_item_sk, SUM(cr.cr_return_quantity) AS total_return_qty, SUM(cr.cr_return_amount) AS total_return_amount, CASE WHEN SUM(cr.cr_return_quantity) > 100 THEN 'HIGH_RETURN' ELSE 'NORMAL_RETURN' END AS return_level, DENSE_RANK() OVER (PARTITION BY d.d_year, d.d_quarter_seq ORDER BY SUM(cr.cr_return_quantity) DESC) AS qty_rank FROM catalog_returns cr JOIN date_dim d ON cr.cr_returned_date_sk = d.d_date_sk GROUP BY d.d_year, d.d_quarter_seq, cr.cr_item_sk) SELECT ri.d_year, ri.d_quarter_seq, ri.cr_item_sk, ri.total_return_qty, ri.total_return_amount, ri.return_level, ri.qty_rank FROM ranked_items ri WHERE ri.qty_rank <= 5 ORDER BY ri.d_year, ri.d_quarter_seq, ri.qty_rank
